package vn.offlinetv.player;

import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.*;import android.graphics.Color;import android.graphics.Bitmap;import android.graphics.drawable.GradientDrawable;import android.media.MediaMetadataRetriever;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity {
 final int BG=0xff101010, PANEL=0xff202020, RED=0xffef3030;
 final ArrayList<Item> items=new ArrayList<>(); final ExecutorService worker=Executors.newSingleThreadExecutor();
 LinearLayout root, content; GridLayout grid; TextView heading; VideoView video; Item playing; String mode="Home"; String query=""; String channel=""; boolean completed=false; String sort="Tên"; String repeat="Tắt"; boolean autoplay=true, shuffle=false; float speed=1f; android.media.MediaPlayer engine; final Handler timer=new Handler(Looper.getMainLooper()); final android.util.LruCache<String,Bitmap> thumbs=new android.util.LruCache<String,Bitmap>(12*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}}; int generation=0; android.content.SharedPreferences prefs;
 static class Item {String title; Uri uri; Item(String t,Uri u){title=t;uri=u;}}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("library",0);sort=prefs.getString("sort","Tên");repeat=prefs.getString("repeat","Tắt");autoplay=prefs.getBoolean("autoplay",true);shuffle=prefs.getBoolean("shuffle",false);getWindow().addFlags(128);home();String permission=Build.VERSION.SDK_INT>=33?android.Manifest.permission.READ_MEDIA_VIDEO:android.Manifest.permission.READ_EXTERNAL_STORAGE;if(checkSelfPermission(permission)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{permission},10);else scan();}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);scan();}
 GradientDrawable bg(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(9));if(stroke!=0)d.setStroke(dp(3),stroke);return d;}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(size);return t;}
 void focus(View v){v.setFocusable(true);v.setBackground(bg(PANEL,0));v.setOnFocusChangeListener((w,f)->{w.setBackground(bg(f?0xff3b3b3b:PANEL,f?Color.WHITE:0));});}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 void nav(LinearLayout side,String label,Runnable action){TextView t=text(label,17);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(15),0,dp(8),0);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(51));p.bottomMargin=dp(8);side.addView(t,p);focus(t);t.setOnClickListener(v->action.run());}
 void home(){video=null;playing=null;root=new LinearLayout(this);root.setBackgroundColor(BG);root.setPadding(dp(20),dp(18),dp(20),dp(15));setContentView(root);LinearLayout side=vertical();root.addView(side,new LinearLayout.LayoutParams(dp(185),-1));TextView brand=text("▶  Offline TV",23);brand.setTextColor(RED);side.addView(brand,new LinearLayout.LayoutParams(-1,dp(65)));
 nav(side,"Trang chủ",()->{mode="Home";query="";render();});nav(side,"Tìm kiếm",()->search());nav(side,"Yêu thích",()->{mode="Fav";render();});nav(side,"Xem tiếp",()->{mode="Recent";render();});nav(side,"Mở thư mục / USB",()->pick());nav(side,"Thư viện khác",()->libraryMenu());nav(side,"Cài đặt",()->settings());
 content=vertical();content.setPadding(dp(18),0,0,0);root.addView(content,new LinearLayout.LayoutParams(0,-1,1));heading=text("Video của bạn",25);content.addView(heading,new LinearLayout.LayoutParams(-1,dp(52)));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));grid=new GridLayout(this);grid.setColumnCount(3);scroll.addView(grid);render();}
 void libraryMenu(){String[] a={"Xem sau","Lịch sử","Kênh / Playlist","Theo thư mục","Quét lại video"};new AlertDialog.Builder(this).setTitle("Thư viện").setItems(a,(d,w)->{if(w==4)scan();else if(w==2)channels();else if(w==3)folders();else{mode=w==0?"Later":"History";render();}}).show();}
 Set<String> set(String k){return new HashSet<>(prefs.getStringSet(k,Collections.emptySet()));}
 void putSet(String k,Set<String> v){prefs.edit().putStringSet(k,v).apply();}
 void channels(){ArrayList<String> names=new ArrayList<>(set("channels"));Collections.sort(names);names.add("+ Tạo kênh / Playlist");new AlertDialog.Builder(this).setTitle("Kênh của bạn").setItems(names.toArray(new String[0]),(d,w)->{if(w==names.size()-1){EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("Tên kênh").setView(e).setPositiveButton("Tạo",(x,y)->{String n=e.getText().toString().trim();if(!n.isEmpty()){Set<String> v=set("channels");v.add(n);putSet("channels",v);}}).setNegativeButton("Hủy",null).show();}else{channel=names.get(w);mode="Channel";render();}}).show();}
 String folder(Item i){String v=i.uri.getLastPathSegment();if(v==null)return "Khác";int n=v.lastIndexOf('/');return n<0?"Bộ nhớ / MediaStore":v.substring(0,n);}
 void folders(){TreeSet<String> f=new TreeSet<>();for(Item i:items)f.add(folder(i));String[] a=f.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Thư mục").setItems(a,(d,w)->{channel=a[w];mode="Folder";render();}).show();}
 void itemMenu(Item i){String[] a={fav(i)?"Bỏ yêu thích":"Yêu thích",set("later").contains(key(i))?"Bỏ xem sau":"Xem sau","Thêm vào kênh / Playlist","Đổi tên hiển thị","Ẩn video"};new AlertDialog.Builder(this).setTitle(name(i)).setItems(a,(d,w)->{if(w==0)toggle(i);if(w==1){Set<String> v=set("later");if(!v.add(key(i)))v.remove(key(i));putSet("later",v);}if(w==2){String[] c=set("channels").toArray(new String[0]);if(c.length==0){channels();return;}new AlertDialog.Builder(this).setTitle("Chọn kênh").setItems(c,(x,y)->{Set<String> v=set("channel:"+c[y]);if(!v.add(key(i)))v.remove(key(i));putSet("channel:"+c[y],v);}).show();}if(w==3){EditText e=new EditText(this);e.setText(name(i));new AlertDialog.Builder(this).setTitle("Tên hiển thị").setView(e).setPositiveButton("Lưu",(x,y)->{prefs.edit().putString("name:"+key(i),e.getText().toString()).apply();render();}).show();}if(w==4){Set<String> v=set("hidden");v.add(key(i));putSet("hidden",v);}render();}).show();}
 String name(Item i){return prefs.getString("name:"+key(i),i.title);}
 void settings(){String[] a={"Sắp xếp: "+sort,"Tự động phát: "+autoplay,"Ngẫu nhiên: "+shuffle,"Lặp: "+repeat,"Hiện lại video đã ẩn","Xóa lịch sử xem","Xóa bộ nhớ đệm ảnh"};new AlertDialog.Builder(this).setTitle("Cài đặt").setItems(a,(d,w)->{if(w==0){String[] z={"Tên","Tên giảm dần","Xem gần đây"};new AlertDialog.Builder(this).setItems(z,(x,y)->{sort=z[y];prefs.edit().putString("sort",sort).apply();render();}).show();}if(w==1){autoplay=!autoplay;prefs.edit().putBoolean("autoplay",autoplay).apply();}if(w==2){shuffle=!shuffle;prefs.edit().putBoolean("shuffle",shuffle).apply();}if(w==3){String[] z={"Tắt","Một video","Danh sách"};new AlertDialog.Builder(this).setItems(z,(x,y)->{repeat=z[y];prefs.edit().putString("repeat",repeat).apply();}).show();}if(w==4){putSet("hidden",new HashSet<>());render();}if(w==5){android.content.SharedPreferences.Editor e=prefs.edit();for(String k:prefs.getAll().keySet())if(k.startsWith("seen:")||k.startsWith("pos:"))e.remove(k);e.apply();render();}if(w==6)thumbs.evictAll();}).show();}
 boolean visible(Item i){String k=key(i);if(set("hidden").contains(k))return false;switch(mode){case "Later":return set("later").contains(k);case "History":return prefs.contains("seen:"+k);case "Channel":return set("channel:"+channel).contains(k);case "Folder":return folder(i).equals(channel);default:return true;}}
 void search(){EditText e=new EditText(this);e.setSingleLine(true);e.setText(query);new AlertDialog.Builder(this).setTitle("Tìm video").setView(e).setPositiveButton("Tìm",(d,w)->{query=e.getText().toString();mode="Search";render();}).setNegativeButton("Hủy",null).show();}
 void pick(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,20);}catch(Exception e){new AlertDialog.Builder(this).setMessage("TV không có trình chọn thư mục. Hãy thử Quét lại video hoặc chép video vào bộ nhớ trong.").setPositiveButton("OK",null).show();}}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==20&&c==RESULT_OK&&d!=null&&d.getData()!=null){Uri u=d.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception e){}Set<String> dirs=new HashSet<>(prefs.getStringSet("dirs",Collections.emptySet()));dirs.add(u.toString());prefs.edit().putStringSet("dirs",dirs).apply();scan();}}
 void scan(){if(heading!=null)heading.setText("Đang tìm video…");final int token=++generation;worker.execute(()->{LinkedHashMap<String,Item> found=new LinkedHashMap<>();try{Uri u=MediaStore.Video.Media.EXTERNAL_CONTENT_URI;try(Cursor c=getContentResolver().query(u,new String[]{"_id","_display_name"},null,null,null)){if(c!=null)while(c.moveToNext()){Uri v=ContentUris.withAppendedId(u,c.getLong(0));found.put(v.toString(),new Item(c.getString(1),v));}}}catch(Exception e){}for(String s:prefs.getStringSet("dirs",Collections.emptySet()))try{Uri t=Uri.parse(s);walk(t,DocumentsContract.getTreeDocumentId(t),found,new HashSet<>(),0);}catch(Exception e){}ArrayList<Item> list=new ArrayList<>(found.values());Collections.sort(list,(a,b)->a.title.compareToIgnoreCase(b.title));runOnUiThread(()->{if(token!=generation)return;items.clear();items.addAll(list);if(video==null)render();});});}
 void walk(Uri tree,String id,Map<String,Item> out,Set<String> seen,int depth){if(depth>40||!seen.add(id))return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=getContentResolver().query(children,new String[]{"document_id","_display_name","mime_type"},null,null,null)){if(c!=null)while(c.moveToNext()){String child=c.getString(0),name=c.getString(1),mime=c.getString(2);if("vnd.android.document/directory".equals(mime))walk(tree,child,out,seen,depth+1);else if((mime!=null&&mime.startsWith("video/"))||name.toLowerCase(Locale.ROOT).matches(".*\\.(mp4|mkv|avi|mov|webm|m4v|ts|3gp|mpeg|mpg)$")){Uri u=DocumentsContract.buildDocumentUriUsingTree(tree,child);out.put(u.toString(),new Item(name,u));}}}catch(Exception e){}}
 String key(Item i){return i.uri.toString();} boolean fav(Item i){return prefs.getBoolean("fav:"+key(i),false);}
 void render(){if(grid==null)return;grid.removeAllViews();heading.setText(mode.equals("Later")?"Xem sau":mode.equals("History")?"Lịch sử xem":mode.equals("Channel")||mode.equals("Folder")?channel:mode.equals("Fav")?"Video yêu thích":mode.equals("Recent")?"Xem tiếp":mode.equals("Search")?"Kết quả tìm kiếm: "+query:"Video của bạn");int width=Math.max(dp(145),(getResources().getDisplayMetrics().widthPixels-dp(255))/3);int n=0;ArrayList<Item> ordered=new ArrayList<>(items);Collections.sort(ordered,(a,b)->sort.equals("Xem gần đây")?Long.compare(prefs.getLong("seen:"+key(b),0),prefs.getLong("seen:"+key(a),0)):sort.equals("Tên giảm dần")?name(b).compareToIgnoreCase(name(a)):name(a).compareToIgnoreCase(name(b)));for(Item i:ordered){if(!visible(i))continue;if(mode.equals("Fav")&&!fav(i)||mode.equals("Recent")&&prefs.getInt("pos:"+key(i),0)<=0||mode.equals("Search")&&!name(i).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;n++;LinearLayout card=vertical();card.setPadding(dp(7),dp(7),dp(7),dp(7));GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=width;p.height=dp(157);p.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(card,p);focus(card);ImageView img=new ImageView(this);img.setScaleType(ImageView.ScaleType.CENTER_CROP);img.setBackgroundColor(0xff343434);img.setImageResource(android.R.drawable.ic_media_play);card.addView(img,new LinearLayout.LayoutParams(-1,dp(100)));TextView label=text((fav(i)?"★ ":"")+name(i),14);label.setMaxLines(2);card.addView(label);card.setOnClickListener(v->play(i));card.setOnLongClickListener(v->{itemMenu(i);return true;});Bitmap cached=thumbs.get(key(i));if(cached!=null)img.setImageBitmap(cached);else if(n<=120)worker.execute(()->{MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(this,i.uri);Bitmap b=m.getFrameAtTime(1000000,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);if(b!=null){Bitmap small=Bitmap.createScaledBitmap(b,320,180,true);thumbs.put(key(i),small);runOnUiThread(()->img.setImageBitmap(small));}}catch(Exception e){}finally{try{m.release();}catch(Exception e){}}});}if(n==0){TextView empty=text("Chưa có video. Chọn Mở thư mục / USB hoặc Quét lại video.",18);grid.addView(empty);}}
 void toggle(Item i){boolean f=!fav(i);prefs.edit().putBoolean("fav:"+key(i),f).apply();Toast.makeText(this,f?"Đã thêm yêu thích":"Đã bỏ yêu thích",Toast.LENGTH_SHORT).show();}
 void play(Item i){if(video!=null)video.stopPlayback();completed=false;playing=i;prefs.edit().putLong("seen:"+key(i),System.currentTimeMillis()).apply();LinearLayout l=vertical();l.setBackgroundColor(Color.BLACK);setContentView(l);TextView title=text(name(i),18);title.setPadding(dp(12),dp(8),0,dp(8));l.addView(title);video=new VideoView(this);l.addView(video,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(this);l.addView(controls);nav(controls,"Quay lại",()->backHome());nav(controls,"Phát / Dừng",()->{if(video.isPlaying())video.pause();else video.start();});nav(controls,"-10 giây",()->video.seekTo(Math.max(0,video.getCurrentPosition()-10000)));nav(controls,"+10 giây",()->video.seekTo(Math.min(video.getDuration(),video.getCurrentPosition()+10000)));nav(controls,"Tùy chọn",()->playerMenu());nav(controls,"Tiếp",()->next(false));for(int j=0;j<controls.getChildCount();j++){View v=controls.getChildAt(j);v.setLayoutParams(new LinearLayout.LayoutParams(0,dp(50),1));}video.setVideoURI(i.uri);video.setOnPreparedListener(m->{engine=m;try{m.setPlaybackParams(m.getPlaybackParams().setSpeed(speed));}catch(Exception ignored){}int pos=prefs.getInt("pos:"+key(i),0);if(pos>0&&pos<m.getDuration()-3000)video.seekTo(pos);video.start();});video.setOnCompletionListener(m->{completed=true;prefs.edit().remove("pos:"+key(i)).apply();next(true);});video.setOnErrorListener((m,w,e)->{new AlertDialog.Builder(this).setMessage("Không phát được video. Định dạng hoặc codec có thể không được TV hỗ trợ.").setPositiveButton("OK",(d,x)->backHome()).show();return true;});controls.getChildAt(1).requestFocus();}
 void next(boolean ended){if(playing==null)return;if(ended&&repeat.equals("Một video")){completed=false;video.seekTo(0);video.start();return;}if(ended&&!autoplay&&!repeat.equals("Danh sách")){backHome();return;}ArrayList<Item> q=new ArrayList<>();for(Item i:items)if(visible(i)&&(!mode.equals("Fav")||fav(i))&&(!mode.equals("Search")||name(i).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT))))q.add(i);int idx=q.indexOf(playing);if(q.isEmpty()){backHome();return;}int j=shuffle&&q.size()>1?(idx+1+new Random().nextInt(q.size()-1))%q.size():idx+1;if(j>=q.size()){if(repeat.equals("Danh sách"))j=0;else{backHome();return;}}if(!ended)save();play(q.get(j));}
 void playerMenu(){String[] a={"Tốc độ phát","Âm thanh","Phụ đề tích hợp","Hẹn giờ dừng","Yêu thích","Xem sau","Đánh dấu vị trí","Đến vị trí đánh dấu"};new AlertDialog.Builder(this).setTitle("Trình phát").setItems(a,(d,w)->{if(video==null)return;if(w==0){String[] z={"0.5x","0.75x","1x","1.25x","1.5x","2x"};float[] r={.5f,.75f,1f,1.25f,1.5f,2f};new AlertDialog.Builder(this).setItems(z,(x,y)->{speed=r[y];try{engine.setPlaybackParams(engine.getPlaybackParams().setSpeed(speed));}catch(Exception e){Toast.makeText(this,"TV không hỗ trợ tốc độ này",Toast.LENGTH_SHORT).show();}}).show();}if(w==1||w==2)tracks(w==1?android.media.MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_AUDIO:android.media.MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_SUBTITLE);if(w==3){String[] z={"Tắt","15 phút","30 phút","60 phút"};new AlertDialog.Builder(this).setItems(z,(x,y)->{timer.removeCallbacksAndMessages(null);if(y>0)timer.postDelayed(()->{save();if(video!=null)video.pause();},new long[]{0,900000,1800000,3600000}[y]);}).show();}if(w==4)toggle(playing);if(w==5){Set<String> v=set("later");v.add(key(playing));putSet("later",v);}if(w==6)prefs.edit().putInt("mark:"+key(playing),video.getCurrentPosition()).apply();if(w==7)video.seekTo(prefs.getInt("mark:"+key(playing),0));}).show();}
 void tracks(int type){try{android.media.MediaPlayer.TrackInfo[] a=engine.getTrackInfo();ArrayList<Integer> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(int i=0;i<a.length;i++)if(a[i].getTrackType()==type){ids.add(i);labels.add(a[i].getLanguage()+" / "+(i+1));}if(ids.isEmpty()){Toast.makeText(this,"Không có track phù hợp",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setItems(labels.toArray(new String[0]),(d,w)->{try{engine.selectTrack(ids.get(w));}catch(Exception ignored){}}).show();}catch(Exception ignored){}}
 void save(){if(video!=null&&playing!=null&&!completed){int p=video.getCurrentPosition();if(p>0&&p<video.getDuration()-1000)prefs.edit().putInt("pos:"+key(playing),p).apply();}}
 void backHome(){save();if(video!=null)video.stopPlayback();home();}
 @Override public void onBackPressed(){if(video!=null)backHome();else super.onBackPressed();}
 @Override protected void onPause(){save();if(video!=null)video.pause();super.onPause();}
 @Override protected void onDestroy(){timer.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
